import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with significant association (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'clinical':  # Only consider non-clinical features
            t_stat = feats.x[:, i].std() * (feats.x[feats.y==1, i].mean() - feats.x[feats.y==0, i].mean())
            p_val = 2 * (1 - stats.t.cdf(abs(t_stat), feats.n - 2))
            if p_val < 0.05:
                sig_features.append((fid, p_val))

    # Sort by significance
    sig_features.sort(key=lambda x: x[1])

    # Check for interaction terms among top features
    top_features = [fid for fid, _ in sig_features[:10]]

    # Look for correlated pairs that might suggest interaction
    correlations = {}
    for i, fid1 in enumerate(top_features):
        for j, fid2 in enumerate(top_features[i+1:], i+1):
            col1 = feats.column(fid1)
            col2 = feats.column(fid2)
            corr = np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0, 1]
            if abs(corr) >= 0.6:
                correlations[(fid1, fid2)] = corr

    # If we have correlations, try to find a strong interaction
    if correlations:
        # Try a simple approach: look for two features with high individual effect
        # and strong correlation
        best_pair = None
        best_p = 1.0
        for (f1, f2), corr in correlations.items():
            col1 = feats.column(f1)
            col2 = feats.column(f2)

            # Create interaction term
            interaction = feats.x[:, col1] * feats.x[:, col2]

            # Test significance of interaction
            _, p_val = stats.pearsonr(interaction, feats.y.astype(float))
            if p_val < best_p:
                best_p = p_val
                best_pair = (f1, f2)

        if best_p < 0.05:
            return Design(
                drivers=(best_pair[0], best_pair[1]),
                columns=(best_pair[0], best_pair[1]),
                products=(best_pair,),
                loadings={}
            )

    # Fall back to single feature approach
    if sig_features:
        # Use the most significant feature
        return Design(
            drivers=(sig_features[0][0],),
            columns=(sig_features[0][0],),
            products=(),
            loadings={sig_features[0][0]: 1.0}
        )

    # No significant features found
    return Design(drivers=(), columns=(), products=(), loadings={})

